before:
foreach ($id in $ids) {
    $vm = Get-VM -Id $id -Server $server
    $vm | Start-VM -Confirm:$false -ErrorAction Stop
    $vm | Stop-VMGuest -Confirm:$false -ErrorAction Stop
}

after:
foreach ($id in $ids) {
    $vm = Get-VM -Id $id -Server $server -ErrorAction Stop
    if (-not $vm) { throw "Missing VM: $id" }
    $running = $vm | Start-VM -TimeoutSeconds 180 -Confirm:$false -ErrorAction Stop
    $running | Stop-ZStackVM -Confirm:$false -ErrorAction Stop
}
